// 리뷰 주제 사전과 최근 동향 집계 — 서버 전용.
//  2026-11-12 전체 리뷰 분석에서 나온 주제를, 고객이 실제로 쓴 표현의 검색식으로 옮긴 것이다(주제 152개).
//   만든 과정: 공식몰·스마트스토어 리뷰 정제 후 35,175건 가운데 40자 이상 리뷰와 별점 3 이하 리뷰 전부, 20~39자 리뷰 5건 중 1건(모두 12,634건)을
//    정독해 주제 1,387개를 뽑고 → 168개로 합치고 → 그중 152개를 검색식으로 만들었다.
//   검증: 검색식마다 걸린 리뷰 40~80건을 직접 읽어 확인 — 맞게 잡는 비율은 152개 모두 90% 이상(가운데값 98%),
//    놓치지 않는 비율은 가운데값 76%(주제마다 다르다 — 각 주제 위 주석). 같은 식을 파이썬과 자바스크립트로 35,175건에 돌려 건수가 전부 일치함을 확인했다.
//  이 검색식으로 센 건수가 '리뷰 분석 자료'(kv review_insight)의 숫자이고, 광고 카피 에이전트가 실행될 때마다 같은 검색식으로
//   최근 90일을 다시 세어 '요즘 늘어난 이야기'를 알려 준다(AI 호출 없음).
//  세는 단위가 다르다는 점: 분석 자료는 '같은 사람이 같은 날 쓴 글은 한 번'(작성 단위 26,044건)으로 셌지만, DB(shop_reviews)에는 작성자가 없어
//   여기서는 '같은 채널의 같은 글은 한 번'으로 센다. 그래서 reviewTrend 의 비율은 자기 자신의 1년 평균과만 견준다(분석 자료의 %와 직접 견주지 않는다).
//  주제를 고치거나 더하면 분석 자료의 숫자와 어긋난다 — 고칠 때는 분석을 다시 돌려 자료도 함께 바꾼다.
//  ※ 아래 REVIEW_THEMES 는 생성된 것이다(분석 산출물 reduce/themes_final.json → 생성 스크립트). 손으로 고치지 않는다.
import type { SupabaseClient } from "@supabase/supabase-js";
import { customerReviewText, normalizeReview, stripSurveyForm } from "./review-clean";

export type ReviewTheme = {
  key: string;
  group: "만족" | "구매계기" | "고객" | "먹는법" | "재구매" | "배송포장" | "가격구성" | "비교" | "걱정반전" | "불만";
  label: string;
  re: RegExp;          // 이 표현이 있으면 그 주제를 말한 리뷰로 센다
  not?: RegExp;        // 이 표현이 함께 있으면 세지 않는다(반대 뜻 걸러내기)
};

