// 리뷰 한 건이 말한 주제들. 설문 양식 리뷰의 고른 칸·고정 질문 문장은 고객의 말이 아니라서 걷어 낸 뒤 센다.
export function themesOf(text: string): string[] {
  const body = stripSurveyForm(text);
  const out: string[] = [];
  for (const t of REVIEW_THEMES) if (t.re.test(body) && !(t.not && t.not.test(body))) out.push(t.key);
  return out;
}

// ── 최근 동향 — 최근 90일 / 그 앞 90일 / 최근 1년, 주제별 건수와 비율 ──
const DAY = 86400_000;
type Row = { channel: string | null; content: string | null; written_at: string | null };
export async function reviewTrend(sb: SupabaseClient, nowMs = Date.now()): Promise<{ ok: boolean; text: string; recent: number }> {
  if (!REVIEW_THEMES.length) return { ok: false, text: "주제 사전이 비어 있습니다.", recent: 0 };
  const since = new Date(nowMs - 365 * DAY).toISOString();
  const rows: Row[] = [];
  for (let from = 0; from < 60_000; from += 1000) {   // 1000행씩 끝까지(1년치는 1만 건 안팎)
    const { data, error } = await sb.from("shop_reviews").select("channel, content, written_at").gte("written_at", since)
      .order("written_at", { ascending: false }).order("id", { ascending: true }).range(from, from + 999);
    if (error) return { ok: false, text: `리뷰 조회 실패: ${String(error.message).slice(0, 120)}`, recent: 0 };
    rows.push(...((data ?? []) as Row[]));
    if (!data || data.length < 1000) break;
  }
  // 자동 문구·복사본을 빼고, 같은 글이 여러 번 달린 것(한 사람이 여러 상품에 같은 글)은 한 번만 센다
  const seen = new Set<string>();
  const win = { r: { n: 0, c: new Map<string, number>() }, p: { n: 0, c: new Map<string, number>() }, y: { n: 0, c: new Map<string, number>() } };
  for (const row of rows) {
    const text = customerReviewText(row.content);
    const at = Date.parse(row.written_at || "");
    if (!text || !Number.isFinite(at)) continue;
    const k = `${row.channel}|${normalizeReview(text)}`;
    if (text.length >= 15 && seen.has(k)) continue;
    seen.add(k);
    const age = (nowMs - at) / DAY;
    const keys = themesOf(text);
    const add = (w: { n: number; c: Map<string, number> }) => { w.n++; for (const key of keys) w.c.set(key, (w.c.get(key) || 0) + 1); };
    add(win.y);
    if (age <= 90) add(win.r); else if (age <= 180) add(win.p);
  }
  if (win.r.n < 30) return { ok: false, text: `최근 90일 리뷰가 ${win.r.n}건뿐이라 동향을 내지 않았습니다.`, recent: win.r.n };
  const pct = (n: number, d: number) => (d ? Math.round((n / d) * 1000) / 10 : 0);
  const lines = REVIEW_THEMES.map((t) => {
    const r = win.r.c.get(t.key) || 0, p = win.p.c.get(t.key) || 0, y = win.y.c.get(t.key) || 0;
    const sr = pct(r, win.r.n), sp = pct(p, win.p.n), sy = pct(y, win.y.n);
    // 눈에 띄는 변화만 표시: 건수가 충분하고(15건 이상) 비율이 1년 평균보다 1.5%p 넘게, 그리고 3할 넘게 달라졌을 때
    const moved = Math.max(r, p) >= 15 && Math.abs(sr - sy) >= 1.5 && Math.abs(sr - sy) / Math.max(sy, 0.1) >= 0.3;
    return { t, r, sr, sp, sy, flag: moved ? (sr > sy ? "늘어남" : "줄어듦") : "" };
  }).filter((x) => x.r >= 5).sort((a, b) => b.sr - a.sr);
  const text = [
    `리뷰 수 — 최근 90일 ${win.r.n}건 · 그 앞 90일 ${win.p.n}건 · 최근 1년 ${win.y.n}건(자동 문구·복사본·같은 글 중복 제외)`,
    "주제 | 최근 90일 건수 | 최근 90일 비율 | 그 앞 90일 비율 | 최근 1년 비율 | 변화",
    ...lines.map((x) => `${x.t.group}·${x.t.label} | ${x.r} | ${x.sr}% | ${x.sp}% | ${x.sy}% | ${x.flag}`),
  ].join("\n");
  return { ok: true, text, recent: win.r.n };
}
